#!/usr/bin/env node

/**
 * Generates per-theme npm packages from the existing plugin/src/themes/ JSON files.
 *
 * Input:
 *   - plugin/src/themes/*.json  (generated by plugin/scripts/generate.js)
 *   - plugin/src/themes/_registry.ts  (theme metadata)
 *   - themes.json  (license info, compatibility, modes)
 *
 * Output:
 *   - packages/{theme-name}/package.json
 *   - packages/{theme-name}/theme.json
 *   - packages/{theme-name}/README.md
 *   - packages/{theme-name}/LICENSE  (if available)
 *   - For collection themes:
 *     - packages/{base}/variants/{variant}.json
 *     - packages/{base}/package.json  (with subpath exports)
 */

import {
  readFileSync,
  writeFileSync,
  mkdirSync,
  readdirSync,
  existsSync,
  cpSync,
} from "node:fs";
import { resolve, join, basename, extname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname =
  import.meta.dirname ?? resolve(fileURLToPath(import.meta.url), "..");
const repoRoot = resolve(__dirname, "..");
const themesDir = join(repoRoot, "plugin", "src", "themes");
const themesJsonPath = join(repoRoot, "themes.json");
const obsidianDir = join(repoRoot, "obsidian");
const outputDir = join(repoRoot, "packages");

const DRY_RUN = process.argv.includes("--dry-run");
const FILTER = process.argv
  .find((a) => a.startsWith("--filter="))
  ?.split("=")[1];

// --- Load metadata ---

const themesJson = JSON.parse(readFileSync(themesJsonPath, "utf8"));
const allThemeMeta = themesJson.themes;

// --- Detect collections from actual JSON filenames ---

function detectCollections() {
  const jsonFiles = readdirSync(themesDir).filter(
    (f) => extname(f) === ".json" && f !== "_baseline.json",
  );

  const themeIds = new Set();
  const fileToId = new Map();

  for (const file of jsonFiles) {
    const id = basename(file, ".json");
    themeIds.add(id);
    fileToId.set(file, id);
  }

  // Dotted IDs from themes.json (the authoritative source)
  const dottedIds = Object.keys(allThemeMeta).filter((id) => id.includes("."));

  // Group: parent → [variant1, variant2, ...]
  const collections = new Map();
  for (const dottedId of dottedIds) {
    const dotIdx = dottedId.indexOf(".");
    const parent = dottedId.substring(0, dotIdx);
    const variant = dottedId.substring(dotIdx + 1);
    if (!collections.has(parent)) collections.set(parent, []);
    collections.get(parent).push(variant);
  }

  // Standalone = everything NOT a dotted ID and NOT _baseline
  const standalones = new Set();
  for (const id of Object.keys(allThemeMeta)) {
    if (id === "_baseline") continue;
    if (!id.includes(".")) standalones.add(id);
  }

  // Collection parents are also standalone themes (they have their own JSON)
  // but they'll be packaged as collections

  return { collections, standalones };
}

// --- File ID mapping ---
// Dotted IDs use dashes in filenames: "catppuccin.frappe" → "catppuccin-frappe.json"
function themeIdToFilename(themeId) {
  return themeId.replace(/[^a-zA-Z0-9-_]/g, "-") + ".json";
}

function readThemeJson(themeId) {
  const filename = themeIdToFilename(themeId);
  const filePath = join(themesDir, filename);
  if (!existsSync(filePath)) return null;
  return readFileSync(filePath, "utf8");
}

// --- Obsidian dir name mapping (display names) ---

function sanitizeToSlug(name) {
  return name
    .toLowerCase()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-]/g, "");
}

const obsidianDirMap = new Map();
if (existsSync(obsidianDir)) {
  for (const dirName of readdirSync(obsidianDir)) {
    const slug = sanitizeToSlug(dirName);
    if (!obsidianDirMap.has(slug)) {
      obsidianDirMap.set(slug, dirName);
    }
  }
}

function findLicenseFile(themeId) {
  const base = themeId.includes(".") ? themeId.split(".")[0] : themeId;
  const dirName = obsidianDirMap.get(base);
  if (!dirName) return null;
  const licensePath = join(obsidianDir, dirName, "LICENSE.md");
  if (existsSync(licensePath)) return licensePath;
  return null;
}

// --- License generation ---

function makeLicenseNotice(themeId, displayName, spdxId, originalLicenseText) {
  let notice = `# License\n\n`;
  notice += `The CSS theme data in this package is derived from the "${displayName}" theme\n`;
  notice += `for Obsidian (https://obsidian.md) and is licensed under ${spdxId} by the\n`;
  notice += `original theme author(s).\n\n`;
  notice += `The packaging, tooling, and adaptation for Quartz are provided by the\n`;
  notice += `quartz-themes project (https://github.com/quartz-themes) under the MIT License.\n`;

  if (originalLicenseText) {
    notice += `\n---\n\n## Original Theme License (${spdxId})\n\n${originalLicenseText}\n`;
  }

  notice += `\n---\n\n## Packaging License (MIT)\n\n`;
  notice += `MIT License\n\n`;
  notice += `Copyright (c) 2024-2026 quartz-themes contributors\n\n`;
  notice += `Permission is hereby granted, free of charge, to any person obtaining a copy\n`;
  notice += `of this software and associated documentation files (the "Software"), to deal\n`;
  notice += `in the Software without restriction, including without limitation the rights\n`;
  notice += `to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n`;
  notice += `copies of the Software, and to permit persons to whom the Software is\n`;
  notice += `furnished to do so, subject to the following conditions:\n\n`;
  notice += `The above copyright notice and this permission notice shall be included in all\n`;
  notice += `copies or substantial portions of the Software.\n\n`;
  notice += `THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\n`;
  notice += `IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\n`;
  notice += `FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\n`;
  notice += `AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\n`;
  notice += `LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\n`;
  notice += `OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\n`;
  notice += `SOFTWARE.\n`;

  return notice;
}

// --- Package generation ---

function makePackageJson(
  name,
  version,
  description,
  license,
  isCollection,
  variants,
) {
  const pkg = {
    name: `@quartz-themes/${name}`,
    version,
    description,
    main: "./theme.json",
    exports: { ".": "./theme.json", "./package.json": "./package.json" },
    files: ["theme.json", "README.md", "LICENSE"],
    keywords: ["quartz", "quartz-theme", "obsidian", name],
    license: license || "MIT",
    publishConfig: { access: "public" },
    repository: {
      type: "git",
      url: `https://github.com/quartz-themes/${name}.git`,
    },
    homepage: `https://quartz-themes.github.io/${name}`,
  };

  if (isCollection && variants.length > 0) {
    pkg.files.push("variants/");
    for (const v of variants) {
      pkg.exports[`./${v}`] = `./variants/${v}.json`;
    }
  }

  return JSON.stringify(pkg, null, 2) + "\n";
}

function makeReadme(name, displayName, modes, license, variants, isCollection) {
  const modeStr = modes.join(" and ");
  const installCmd = `npm install @quartz-themes/core @quartz-themes/${name}`;

  let content = `# ${displayName || name}\n\n`;
  content += `Obsidian theme adapted for [Quartz](https://github.com/jackyzha0/quartz).\n\n`;
  content += `**Modes**: ${modeStr}\n`;
  content += `**License**: ${license || "MIT"}\n\n`;
  content += `## Installation\n\n\`\`\`bash\n${installCmd}\n\`\`\`\n\n`;
  const mode =
    modes.includes("dark") && modes.includes("light") ? "both" : modes[0];
  content += `## Usage\n\n\`\`\`yaml\n# quartz.config.yaml\nplugins:\n  - source: "@quartz-themes/core"\n    options:\n      theme: "${name}"\n      mode: "${mode}"\n\`\`\`\n`;

  if (isCollection && variants.length > 0) {
    content += `\n## Variants\n\n`;
    for (const v of variants) {
      content += `- \`${name}.${v}\`\n`;
    }
    content += `\n\`\`\`yaml\nplugins:\n  - source: "@quartz-themes/core"\n    options:\n      theme: "${name}"\n      variation: "${variants[0]}"\n      mode: "${mode}"\n\`\`\`\n`;
  }

  content += `\n## Preview\n\n[Live preview](https://quartz-themes.github.io/${name})\n`;

  return content;
}

// --- Main ---

function main() {
  const { collections, standalones } = detectCollections();

  console.log(`Detected ${standalones.size} standalone themes`);
  console.log(`Detected ${collections.size} collection parents with variants:`);
  for (const [parent, variants] of collections) {
    console.log(
      `  ${parent}: ${variants.length} variants (${variants.join(", ")})`,
    );
  }

  if (DRY_RUN) {
    const totalPackages = standalones.size;
    // Collection parents are in standalones too, but they become collection packages
    console.log(`\nDry run: would generate ${totalPackages} packages`);
    return;
  }

  mkdirSync(outputDir, { recursive: true });

  let generated = 0;
  let skipped = 0;
  let errors = 0;

  // Process all standalone themes (includes collection parents)
  for (const themeId of standalones) {
    if (FILTER && themeId !== FILTER) continue;

    const isCollection = collections.has(themeId);
    const variants = isCollection ? collections.get(themeId) : [];

    try {
      const packageDir = join(outputDir, themeId);
      mkdirSync(packageDir, { recursive: true });

      // Read base theme JSON
      const themeJson = readThemeJson(themeId);
      if (!themeJson) {
        console.error(`  SKIP: ${themeId} — no JSON file found`);
        skipped++;
        continue;
      }

      // Write theme.json
      writeFileSync(join(packageDir, "theme.json"), themeJson);

      // Get metadata
      const meta = allThemeMeta[themeId] || {};
      const license = meta.license?.spdx_id || "MIT";
      const modes = meta.modes || ["dark", "light"];
      const displayName = themeId
        .split("-")
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(" ");

      // Write package.json
      const pkgJson = makePackageJson(
        themeId,
        "1.0.0",
        `${displayName} theme for Quartz`,
        license,
        isCollection,
        variants,
      );
      writeFileSync(join(packageDir, "package.json"), pkgJson);

      // Write README.md
      const readme = makeReadme(
        themeId,
        displayName,
        modes,
        license,
        variants,
        isCollection,
      );
      writeFileSync(join(packageDir, "README.md"), readme);

      // Write dual-license notice
      const originalLicensePath = findLicenseFile(themeId);
      const originalLicenseText = originalLicensePath
        ? readFileSync(originalLicensePath, "utf8").trim()
        : null;
      const licenseNotice = makeLicenseNotice(
        themeId,
        displayName,
        license,
        originalLicenseText,
      );
      writeFileSync(join(packageDir, "LICENSE"), licenseNotice);

      // Handle collection variants
      if (isCollection) {
        const variantsDir = join(packageDir, "variants");
        mkdirSync(variantsDir, { recursive: true });

        for (const variant of variants) {
          const variantId = `${themeId}.${variant}`;
          const variantJson = readThemeJson(variantId);
          if (!variantJson) {
            console.error(
              `  WARN: ${variantId} — no JSON file found, skipping variant`,
            );
            continue;
          }
          writeFileSync(join(variantsDir, `${variant}.json`), variantJson);
        }
      }

      generated++;
      if (generated % 50 === 0) {
        console.log(`  Generated ${generated} packages...`);
      }
    } catch (err) {
      console.error(`  ERROR: ${themeId} — ${err.message}`);
      errors++;
    }
  }

  console.log(
    `\nDone: ${generated} packages generated, ${skipped} skipped, ${errors} errors`,
  );
  console.log(`Output: ${outputDir}`);

  // Summary stats
  const totalVariantFiles = [...collections.values()].reduce(
    (sum, v) => sum + v.length,
    0,
  );
  console.log(
    `  Collection packages: ${collections.size} (containing ${totalVariantFiles} variant files)`,
  );
  console.log(`  Standalone packages: ${generated - collections.size}`);
}

main();
